INSERT INTO `projects` (`id`, `parent_id`, `project_code`, `name`, `description`, `fiscal_year_id`, `category_id`, `department_id`, `responsible_user_id`, `start_date`, `end_date`, `budget`, `disbursed_amount`, `status`, `progress`, `progress_mode`) VALUES
(1, NULL, 'PRJ-2568-001', 'โครงการพัฒนาคุณภาพชีวิตและส่งเสริมสุขภาพประชาชนแบบยั่งยืน', 'โครงการบูรณาการเพื่อดูแลสุขภาพของประชาชนทุกกลุ่มวัย ทั้งผู้สูงอายุ วัยทำงาน และเด็กในเขตเทศบาล', 2, 2, 2, 3, '2024-10-01', '2025-09-30', 1000000.00, 650000.00, 'in_progress', 68.33, 'auto'),
(2, NULL, 'PRJ-2568-002', 'โครงการยกระดับโครงสร้างพื้นฐานและเมืองน่าอยู่อัจฉริยะ', 'โครงการปรับปรุงระบบคมนาคม ผิวจราจร และระบบไฟส่องสว่างพลังงานแสงอาทิตย์ทั่วเขตเทศบาล', 2, 1, 1, 4, '2024-11-01', '2025-08-31', 3500000.00, 1850000.00, 'in_progress', 45.00, 'auto'),
(3, NULL, 'PRJ-2568-003', 'โครงการจัดการขยะชุมชนและอนุรักษ์สิ่งแวดล้อม', 'โครงการรณรงค์คัดแยกขยะต้นทาง จัดตั้งธนาคารขยะ และลดมลพิษทางอากาศ', 2, 4, 2, 3, '2025-01-01', '2025-07-31', 600000.00, 0.00, 'not_started', 0.00, 'auto');
